    def test_no_due_date_not_overdue(self):
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(self.NOW) is False

    def test_done_task_not_overdue(self):
        task = Task(id=1, title="t", status=TaskStatus.DONE,
                    due_at=self.NOW - timedelta(days=1))
        assert task.is_overdue(self.NOW) is False

    def test_past_due_pending_is_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW - timedelta(hours=1))
        assert task.is_overdue(self.NOW) is True

    def test_future_due_not_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW + timedelta(days=1))
        assert task.is_overdue(self.NOW) is False

    def test_due_exactly_at_now_not_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW)
        assert task.is_overdue(self.NOW) is False


